// external module nmi_psram

module PSRAMWrapper(
  input         clock,
                reset,
                io_in_psel,
                io_in_penable,
                io_in_pwrite,
  input  [31:0] io_in_paddr,
                io_in_pwdata,
  input  [3:0]  io_in_pstrb,
  output        io_in_pready,
  output [31:0] io_in_prdata,
  output        io_qspi_spi_sck_o,
  output [3:0]  io_qspi_spi_nss_o,
                io_qspi_spi_io_en_o,
  input  [3:0]  io_qspi_spi_io_in_i,
  output [3:0]  io_qspi_spi_io_out_o
);

  wire        _npsram_nmi_ready;
  reg  [31:0] addrReg;
  reg  [31:0] wdataReg;
  reg  [3:0]  wstrbReg;
  reg         active;
  always @(posedge clock) begin
    automatic logic setup;
    setup = io_in_psel & ~io_in_penable;
    if (~active & setup) begin
      automatic logic [3:0][31:0] _GEN =
        {{{24'h0, io_in_pwdata[31:24]}},
         {{16'h0, io_in_pwdata[31:16]}},
         {{8'h0, io_in_pwdata[31:8]}},
         {io_in_pwdata}};
      addrReg <= {7'h20, io_in_paddr[24:2], 2'h0};
      wdataReg <= _GEN[io_in_paddr[1:0]];
      wstrbReg <= io_in_pwrite ? io_in_pstrb : 4'h0;
    end
    if (reset)
      active <= 1'h0;
    else if (active)
      active <= ~_npsram_nmi_ready;
    else
      active <= setup;
  end // always @(posedge)
  `ifdef ENABLE_INITIAL_REG_
    `ifdef FIRRTL_BEFORE_INITIAL
      `FIRRTL_BEFORE_INITIAL
    `endif // FIRRTL_BEFORE_INITIAL
    initial begin
      automatic logic [31:0] _RANDOM[0:2];
      `ifdef INIT_RANDOM_PROLOG_
        `INIT_RANDOM_PROLOG_
      `endif // INIT_RANDOM_PROLOG_
      `ifdef RANDOMIZE_REG_INIT
        for (logic [1:0] i = 2'h0; i < 2'h3; i += 2'h1) begin
          _RANDOM[i] = `RANDOM;
        end
        addrReg = _RANDOM[2'h0];
        wdataReg = _RANDOM[2'h1];
        wstrbReg = _RANDOM[2'h2][3:0];
        active = _RANDOM[2'h2][4];
      `endif // RANDOMIZE_REG_INIT
    end // initial
    `ifdef FIRRTL_AFTER_INITIAL
      `FIRRTL_AFTER_INITIAL
    `endif // FIRRTL_AFTER_INITIAL
  `endif // ENABLE_INITIAL_REG_
  nmi_psram npsram (
    .clk_i             (clock),
    .rst_n_i           (~reset),
    .nmi_valid         (active),
    .nmi_addr          (addrReg),
    .nmi_wdata         (wdataReg),
    .nmi_wstrb         (wstrbReg),
    .nmi_rdata         (io_in_prdata),
    .nmi_ready         (_npsram_nmi_ready),
    .qspi_spi_sck_o    (io_qspi_spi_sck_o),
    .qspi_spi_nss_o    (io_qspi_spi_nss_o),
    .qspi_spi_io_en_o  (io_qspi_spi_io_en_o),
    .qspi_spi_io_in_i  (io_qspi_spi_io_in_i),
    .qspi_spi_io_out_o (io_qspi_spi_io_out_o),
    .qspi_irq_o        (/* unused */)
  );
  assign io_in_pready = ~active | _npsram_nmi_ready;
endmodule

